  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const id = getRouterParam(event, 'id') ?? ''
  const payload = await readBody<{ title?: unknown; body?: unknown; action?: unknown }>(event)
  // The Cancel button submits the same form without JavaScript.
  if (form && payload?.action === 'cancel') return sendRedirect(event, '/notes', 303)
  const existing = findNote(name, id)
  if (!existing) {
    if (form) return sendRedirect(event, '/notes', 303)
    throw createError({ statusCode: 404, statusMessage: 'Note not found' })
  }
  if (existing.archived) {
    if (form) return sendRedirect(event, '/archive', 303)
    throw createError({ statusCode: 409, statusMessage: ARCHIVED_ERROR, data: { code: 'archived' } })
  }
  const fail = (code: string) => sendRedirect(event, `/notes?edit=${encodeURIComponent(id)}&editError=${code}`, 303)

  // The note's own page sends a `body` field (even when empty); the list's inline title-only edit does not.
  const hasBody = typeof payload?.body === 'string'
  const rawTitle = typeof payload?.title === 'string' ? payload.title : ''
  const title = rawTitle.trim()
  const rawBody = hasBody ? (payload.body as string) : ''
  const bodyText = rawBody.trim()

  let titleCode: string | null = null
  if (title.length < 1) titleCode = 'invalid'
  else if (title.length > NOTE_MAX_LENGTH) titleCode = 'too-long'
  else if (noteExists(name, title, id)) titleCode = 'duplicate'

  const bodyCode = hasBody && bodyText.length > NOTE_BODY_MAX_LENGTH ? 'body-too-long' : null

  if (titleCode || bodyCode) {
    if (form) {
      if (hasBody) {
        const query = new URLSearchParams()
        if (titleCode) query.set('titleError', titleCode)
        if (bodyCode) query.set('bodyError', bodyCode)
        query.set('title', rawTitle)
        query.set('body', rawBody)
        return sendRedirect(event, `/notes/${existing.number}?${query.toString()}`, 303)
      }
      return fail(titleCode ?? 'invalid')
    }
    const statusMessage = titleCode === 'invalid'
      ? `Note must be 1-${NOTE_MAX_LENGTH} characters`
      : titleCode === 'too-long'
        ? `Use at most ${NOTE_MAX_LENGTH} characters`
        : titleCode === 'duplicate'
          ? 'You already have a note with this title'
          : `Use at most ${NOTE_BODY_MAX_LENGTH} characters in the body`
    const statusCode = titleCode === 'duplicate' ? 409 : 400
    throw createError({
      statusCode,
      statusMessage,
      data: hasBody ? { titleCode, bodyCode } : { code: titleCode },
    })
  }

  const note = renameNote(name, id, title, hasBody ? bodyText : undefined)
  if (form) return sendRedirect(event, hasBody ? `/notes/${existing.number}?saved=1` : '/notes', 303)
  return note
})

